<?php
namespace App\Http\Controllers\Transactions;
use App\Http\Controllers\Controller; use App\Http\Requests\Adjustment\CreateAdjustmentRequest; use App\Models\Adjustment; use App\Services\Adjustment\AdjustmentService; use Illuminate\Http\Request;
class AdjustmentController extends Controller { public function __construct(){ $this->middleware('menu.permission:transactions.adjustment,view')->only(['index','create']);$this->middleware('menu.permission:transactions.adjustment,reverse')->only('store'); } public function index(Request $r){$query=Adjustment::query();if($r->filled('document_number'))$query->where('document_number',$r->input('document_number'));return view('transactions.adjustments.index',['rows'=>$query->latest('posted_at')->paginate(30)->withQueryString()]);} public function create(Request $r){return view('transactions.adjustments.create',['type'=>$r->input('ledger_type'),'sourceId'=>$r->input('source_entry_id')]);} public function store(CreateAdjustmentRequest $r,AdjustmentService $service){$d=$r->validated();$adj=$service->reverse($d['ledger_type'],(int)$d['source_entry_id'],$d['reason'],$r->user());return redirect()->route('adjustments.index')->with('success','Reversal posted: '.$adj->document_number);} }
